<?php
require __DIR__.'/bootstrap.php';if(!str_ends_with((string)g('SELECT DATABASE()'),'_test'))throw new RuntimeException('Disposable test database required.');date_default_timezone_set('Africa/Lagos');$_SESSION=['csrf'=>'race'];
function ra(int $uid,string $a,array $p=[]):void{$_SESSION['u']=q('SELECT * FROM users WHERE id=?',[$uid])->fetch();$_POST=['csrf'=>'race','op_action'=>$a]+$p;op_action(op_actor());}
$worker=tempnam(sys_get_temp_dir(),'ops-race-').'.php';$code= <<<'WORKER'
<?php
require BOOTSTRAP;date_default_timezone_set('Africa/Lagos');$_SESSION=['csrf'=>'race','u'=>q('SELECT * FROM users WHERE id=?',[(int)$argv[1]])->fetch()];
try{$_POST=['csrf'=>'race']+json_decode($argv[2],true,512,JSON_THROW_ON_ERROR);op_action(op_actor());echo 'OK';}catch(Throwable $e){echo 'DENIED';}
WORKER;
file_put_contents($worker,str_replace('BOOTSTRAP',var_export(__DIR__.'/bootstrap.php',true),$code));
function race(array $jobs):array{global $worker;$all=[];foreach($jobs as [$uid,$post]){$pipes=[];$proc=proc_open([PHP_BINARY,'-c',php_ini_loaded_file(),$worker,(string)$uid,json_encode($post)],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$all[]=[$proc,$pipes];}$out=[];foreach($all as [$proc,$pipes]){$out[]=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($proc)!==0||$err)throw new RuntimeException($err);}sort($out);return $out;}
$n=0;function check($v,string $m){global $n;if(!$v)throw new RuntimeException($m);echo 'PASS '.$m."\n";$n++;}
ra(13,'hr_generate',['period'=>'2026-12']);$run=(int)g('SELECT MAX(id) FROM hr_payruns');ra(2,'hr_approve_run',['run_id'=>$run]);$job=[2,['op_action'=>'hr_pay_run','run_id'=>$run,'payment_ref'=>'RACE-PAY']];check(race([$job,$job])===['DENIED','OK'],'parallel payroll confirmation posts only once');check((int)g('SELECT COUNT(*) FROM fn_journal WHERE entry_ref LIKE ?',['HR-PAY-'.$run.'-%'])===8,'parallel payroll has exactly four balanced journal pairs');
$route=(int)g('SELECT MAX(id) FROM tm_routes');$stop=(int)g('SELECT MAX(id) FROM tm_stops');$out=race([[2,['op_action'=>'tm_assign','student_id'=>1,'route_id'=>$route,'stop_id'=>$stop]],[2,['op_action'=>'tm_assign','student_id'=>2,'route_id'=>$route,'stop_id'=>$stop]]]);check($out===['DENIED','OK']&&(int)g("SELECT COUNT(*) FROM tm_assignments WHERE route_id=? AND status='active'",[$route])===1,'parallel assignments cannot exceed one-seat vehicle capacity');
$student=(int)g("SELECT student_id FROM tm_assignments WHERE route_id=? AND status='active'",[$route]);$job=[2,['op_action'=>'tm_fee','student_id'=>$student,'period'=>'RACE-PERIOD']];check(race([$job,$job])===['OK','OK']&&(int)g('SELECT COUNT(*) FROM fn_invoices WHERE reference=?',['OPS-TM-'.$student.'-RACE-PERIOD'])===1,'parallel fee retries create one invoice');
$h=(int)g('SELECT MAX(id) FROM hostels');ra(2,'bd_room',['hostel_id'=>$h,'name'=>'Race room','capacity'=>1]);$room=(int)g('SELECT MAX(id) FROM bd_rooms');ra(2,'bd_bed',['room_id'=>$room,'name'=>'Race bed']);$bed=(int)g('SELECT MAX(id) FROM bd_beds');check(race([[2,['op_action'=>'bd_allocate','student_id'=>2,'bed_id'=>$bed,'starts_on'=>date('Y-m-d')]],[2,['op_action'=>'bd_allocate','student_id'=>3,'bed_id'=>$bed,'starts_on'=>date('Y-m-d')]]])===['DENIED','OK'],'parallel residents cannot allocate one bed twice');
$supply=(int)g('SELECT MAX(id) FROM bd_supplies');$job=[15,['op_action'=>'bd_stock','supply_id'=>$supply,'delta'=>'-2','note'=>'Concurrent issue']];check(race([$job,$job])===['DENIED','OK']&&(int)g('SELECT quantity FROM bd_supplies WHERE id=?',[$supply])===1,'parallel stock issues cannot make supplies negative');
unlink($worker);echo 'TOTAL '.$n." passed\n";
